/** Complete original primitive/label/report checks plus source-specific native equations; no independent draws/kernel fitting. */
final class GseapyExecutionAudit {
    private GseapyExecutionAudit(){ }
    record Key(String name,String term){ }
    static final class Meter {
        final long maximum;long used,numeric,identities,tsv,nonfinite;
        Meter(long maximum){this.maximum=maximum;}
        void charge(long amount)throws IOException{require(amount>=0&&amount<=maximum-used,"Complete native audit operation capacity exceeded; no partial family admitted");used+=amount;}
    }
    static Map<String,Object> analyze(Map<String,Object> specification,Path home,GseapyWorkflowInputs.Prepared input,GseapyWorkflowRequest.Request request,List<String> warnings,Meter meter)throws IOException{
        String method=text(specification.get("method")),id=text(specification.get("id"));var policies=object(specification.get("policies"));var options=object(specification.get("options"));var returned=GseapyExecutionRuntime.read(home.resolve("original-return.json"),67108864);var effective=GseapyExecutionRuntime.read(home.resolve("effective-options-before-run.json"),16777216);require(text(effective.get("interface")).equals("original-class")&&sameData(object(effective.get("requested")),options,meter),"Original scientific options were changed before construction");require(sameData(GseapyExecutionRuntime.read(home.resolve("source-input.json"),Math.toIntExact(Math.min(request.inputBytes(),1000000000))),input.raw(),meter),"Original worker used different prepared input");
        var table=ScfatesWorkflowData.frame(home,returned.get("res2d")!=null?returned.get("res2d"):returned.get("results"),request.maximumMatrixCells()).values();if(table.rows()==0)policy(policies,"empty_results",warnings,id+": original result family is empty; no enriched/active result is inferred");
        long beforeNonfinite=meter.nonfinite;scan(home,returned,request,meter);Map<String,Object> detail;
        if(method.equals("enrichr")){detail=enrichr(specification,home,table,request,warnings,meter);var tested=GseapyExecutionRuntime.read(home.resolve("observed-enrichr-test.json"),67108864);if(!ids(tested.get("query")).equals(ids(input.raw().get("query"))))policy(policies,"source_input_changes",warnings,id+": original local-Enrichr parsing/case conversion changed query identities; preserve raw and effective queries without automatically repairing identifiers");}
        else detail=ranked(specification,home,table,returned,request,warnings,meter);
        long nonfinite=meter.nonfinite-beforeNonfinite;if(nonfinite>0)policy(policies,"nonfinite_diagnostics",warnings,id+": original primitive states contain "+nonfinite+" nonfinite values. Retain the exact NaN/Inf states; do not insert epsilon, renormalize, clip or treat them as finite evidence");
        if(Boolean.TRUE.equals(returned.get("_gene_toupper")))policy(policies,"source_input_changes",warnings,id+": original package converted gene identifiers to uppercase for membership matching; raw input/metric/report labels are retained");
        if(!method.equals("enrichr")){
            var observed=GseapyExecutionRuntime.read(home.resolve("observed-backend-summary.json"),67108864);var rawIds=list(input.raw().get("ids"));for(Object raw:object(observed.get("metric")).values()){var active=ids(object(raw).get("index"));if(active.size()!=rawIds.size()||!new HashSet<>(active).equals(new HashSet<>(rawIds)))policy(policies,"source_input_changes",warnings,id+": original backend gene family differs from the raw input through source aggregation/filtering; do not infer one-to-one raw-row correspondence");}
            Object processed=returned.get(method.equals("ssgsea")?"ranking":"data");if(processed instanceof Map<?,?> raw&&"dataframe".equals(raw.get("kind"))){var frame=ScfatesWorkflowData.frame(home,processed,request.maximumMatrixCells());if(!new HashSet<>(frame.ids()).equals(new HashSet<>(rawIds))||frame.rows()!=rawIds.size())policy(policies,"source_input_changes",warnings,id+": source preprocessing changed the gene family/order multiplicity; retain duplicate-aggregation/filtering evidence and do not infer a one-to-one input correspondence");}
            if(method.equals("gsva")&&"Poisson".equals(options.get("kcdf"))){long negative=0;for(Object row:list(input.raw().get("values")))for(Object value:list(row))if(scalar(value)<0)negative++;if(negative>0)policy(policies,"source_input_changes",warnings,id+": prepared input contains "+negative+" negative values, and original Poisson GSVA clips negative values after source preprocessing. Raw and effective matrices remain separately captured; this raw count is not a claim of one-to-one post-aggregation clipping. No Java correction is substituted");}
        }
        tsv(home.resolve("full-result.tsv"),table,request.outputBytes(),meter);var out=new LinkedHashMap<String,Object>(detail);out.put("id",id);out.put("method",method);out.put("rows",table.rows());out.put("nonfinite_states",nonfinite);out.put("independent_permutations",false);out.put("independent_gsva_kernel",false);return out;
    }
    private static Map<String,Object> enrichr(Map<String,Object> specification,Path home,CellPhoneDbWorkflowData.Frame table,GseapyWorkflowRequest.Request request,List<String> warnings,Meter meter)throws IOException{
        var observed=GseapyExecutionRuntime.read(home.resolve("observed-enrichr-test.json"),67108864);var statistics=GseapyExecutionRuntime.read(home.resolve("observed-enrichr-statistics.json"),67108864);var query=ids(observed.get("query"));var sets=new LinkedHashMap<String,List<String>>();for(var e:object(observed.get("gene_sets")).entrySet())sets.put(e.getKey(),ids(e.getValue()));Object background=observed.get("background");GseapyStatistics.Background bg=background instanceof Map<?,?>?new GseapyStatistics.Universe(Set.copyOf(ids(background))):new GseapyStatistics.Population(Math.toIntExact(integer(background,0,Integer.MAX_VALUE)));var edition=GseapyStatistics.Edition.valueOf("V"+request.edition().replace('.','_'));var rows=GseapyStatistics.overRepresentation(edition,query,sets,bg,finite(object(specification.get("options")).get("cutoff"),0,1));var raw=list(statistics.get("values"));require(rows.size()==raw.size()&&rows.size()==table.rows(),"Original local-enrichment complete term family differs");var expectedTerms=new HashSet<String>();var rowIndex=new LinkedHashMap<String,Integer>();for(int row=0;row<table.rows();row++){require(rowIndex.put(text(table.value(row,"Term")),row)==null,"Duplicate original local-enrichment term");meter.charge(1);}
        for(int i=0;i<rows.size();i++){
            var expected=rows.get(i);var value=list(raw.get(i));require(value.size()==6&&expected.term().equals(text(value.get(0)))&&expected.overlap()==integer(value.get(3),0,Integer.MAX_VALUE)&&expected.termSize()==integer(value.get(4),0,Integer.MAX_VALUE)&&new HashSet<>(expected.hits()).equals(new HashSet<>(ids(value.get(5)))),"Original Enrichr term, count or literal hit identity differs");meter.identities+=4+expected.hits().size();same(expected.pValue(),scalar(value.get(1)),5e-12,meter,"Enrichr original tail");same(expected.oddsRatio(),scalar(value.get(2)),0,meter,"Enrichr edition odds");Integer at=rowIndex.get(expected.term());require(at!=null,"Missing original local-enrichment term");require(expectedTerms.add(expected.term())&&text(table.value(at,"Overlap")).equals(expected.overlap()+"/"+expected.termSize()),"Original Enrichr overlap annotation changed");same(expected.pValue(),table.number(at,"P-value"),5e-12,meter,"Enrichr reported P");same(expected.adjustedPValue(),table.number(at,"Adjusted P-value"),5e-12,meter,"Enrichr correction family");same(expected.oddsRatio(),table.number(at,"Odds Ratio"),0,meter,"Enrichr reported odds");
            require(text(table.value(at,"Genes")).equals(String.join(";",ids(value.get(5)))),"Original ordered hit annotation changed");
            if(expected.combinedScoreAvailable()){
                double source=table.number(at,"Combined Score");if(Double.isFinite(source)&&source!=0){double bound=Math.abs(Math.log(expected.pValue())-Math.log(table.number(at,"P-value")))*Math.abs(expected.oddsRatio())+16*Math.ulp(source);require(Math.abs(expected.combinedScore()-source)<=bound,"Original combined score outside measured-tail/log envelope");meter.numeric++;}else same(expected.combinedScore(),source,0,meter,"Enrichr combined score kind");
            }else require(!table.columns().contains("Combined Score"),"Combined-score column invented for original1.0.4 local Enrichr");
            for(String warning:expected.warnings())warnings.add(text(specification.get("id"))+": "+warning);
        }
        return Map.of("native_local_tests",rows.size(),"one_sided_upper_tail",true,"remote_Enrichr_response_reproduced",false);
    }
    private static Map<String,Object> ranked(Map<String,Object> specification,Path home,CellPhoneDbWorkflowData.Frame table,Map<String,Object> returned,GseapyWorkflowRequest.Request request,List<String> warnings,Meter meter)throws IOException{
        String method=text(specification.get("method"));var options=object(specification.get("options"));var observed=GseapyExecutionRuntime.read(home.resolve("observed-backend-summary.json"),67108864);var summaries=list(observed.get("summaries"));var metric=object(observed.get("metric"));var metricNames=object(observed.get("metric_dict"));var byKey=new LinkedHashMap<Key,Map<String,Object>>();var groups=new LinkedHashMap<String,List<Map<String,Object>>>();long permutations=method.equals("gsva")?0:integer(options.get("permutation_num"),0,1000000);int walks=0;
        for(Object raw:summaries){var s=object(raw);String name=s.get("index")==null?method:text(metricNames.get(Long.toString(integer(s.get("index"),0,1000000))));String term=text(s.get("term"));require(byKey.put(new Key(name,term),s)==null,"Duplicate original backend result identity");groups.computeIfAbsent(method.equals("ssgsea")?name:"whole-family",key->new ArrayList<>()).add(s);var series=object(metric.get(name));var labels=ids(series.get("index"));var values=ScfatesWorkflowData.vector(home,series.get("data"),request.maximumMatrixCells());require(values.size()==labels.size(),"Original complete ranked axis differs");var rawHits=list(s.get("hits"));int[] hits=new int[rawHits.size()];var unique=new HashSet<Integer>();for(int i=0;i<hits.length;i++){hits[i]=Math.toIntExact(integer(rawHits.get(i),0,labels.size()-1));require(unique.add(hits[i])&&(i==0||hits[i]>hits[i-1]),"Original hits are duplicated or out of rank order");}meter.identities+=labels.size()+hits.length;double[] run=vector(s.get("run_es"));
            if(!method.equals("gsva")){
                double exponent=finite(options.get("weight"),0,8);double[] weights=new double[values.size()],signed=new double[values.size()];for(int i=0;i<weights.length;i++)signed[i]=values.number(i);
                if(method.equals("ssgsea")&&exponent>0&&text(options.get("correl_norm_type")).equals("zscore")){double mean=0;for(double v:signed)mean+=v;mean/=signed.length;double variance=0;for(double v:signed){double delta=mean-v;variance+=delta*delta;}double sd=Math.sqrt(variance/signed.length);for(int i=0;i<weights.length;i++)weights[i]=Math.pow(Math.abs((signed[i]-mean)/sd),exponent);}
                else for(int i=0;i<weights.length;i++)weights[i]=Math.pow(Math.abs(signed[i]),exponent);
                meter.charge(20L*weights.length);var computed=GseapyRankedStatistics.walk(weights,hits);double[] dense=method.equals("gsea")&&!request.edition().equals("1.1.8")&&text(options.get("permutation_type")).equals("phenotype")?GseapyRankedStatistics.rawRunning(signed,hits):computed.running();if(run.length>0){require(run.length==dense.length,"Incomplete original running curve");for(int i=0;i<run.length;i++)same(dense[i],run[i],2e-12,meter,"Original dense curve");}
                double es=method.equals("ssgsea")?computed.singleSampleScore():computed.sparseScore();same(es,scalar(s.get("es")),2e-12,meter,"Original observed enrichment score");walks++;
            }
            if(run.length>1)leading(home,s,name,labels,hits,run,object(observed.get("gmt")),returned,meter);
        }
        if(method.equals("ssgsea")&&permutations==0){double[] es=new double[summaries.size()];for(int i=0;i<es.length;i++)es[i]=scalar(object(summaries.get(i)).get("es"));double[] normalized=GseapyRankedStatistics.normalizeSingleSample(es);for(int i=0;i<es.length;i++)same(normalized[i],scalar(object(summaries.get(i)).get("nes")),0,meter,"Complete ssGSEA normalization family");}
        if(permutations>0){
            for(var group:groups.values()){
                double[] es=new double[group.size()];double[][] nulls=new double[group.size()][];for(int i=0;i<es.length;i++){es[i]=scalar(group.get(i).get("es"));nulls[i]=vector(group.get(i).get("esnull"));require(nulls[i].length==permutations,"Original null draws do not match declared count");}meter.charge(Math.multiplyExact(80L*es.length,permutations));var computed=GseapyRankedStatistics.fromNulls(es,nulls);double[] nes=computed.normalizedScores(),p=computed.nominalP(),q=computed.fdr(),fwer=computed.familywiseP();for(int i=0;i<es.length;i++){same(nes[i],scalar(group.get(i).get("nes")),0,meter,"Original NES");same(p[i],scalar(group.get(i).get("pval")),0,meter,"Original nominal P");same(q[i],scalar(group.get(i).get("fdr")),0,meter,"Original pooled-tail FDR");same(fwer[i],scalar(group.get(i).get("fwerp")),0,meter,"Original columnwise FWER");}
            }
            if(method.equals("ssgsea"))warnings.add(text(specification.get("id"))+": original GSEApy warns against using permuted ssGSEA P/FDR results for publication; these are retained original diagnostics, without independent permutation calibration");
        }
        if((method.equals("gsea")||method.equals("prerank"))&&permutations==0)warnings.add(text(specification.get("id"))+": original zero-permutation NES fields remain uncomputed placeholders. Only the observed ES is calculated; do not interpret placeholder NES or hidden zero P/FDR/FWER slots as inference");
        if(method.equals("ssgsea")&&text(options.get("correl_norm_type")).equals("symrank"))warnings.add(text(specification.get("id"))+": the captured original SymRank branch discards its expression without assigning a transformed value. Native checking retains that source behavior; it does not replace it with a newly implemented symmetric-rank transform");
        if(method.equals("gsea")&&text(options.get("permutation_type")).equals("phenotype")){warnings.add(text(specification.get("id"))+": phenotype running-curve convention is edition-specific:1.0.4/1.1.2/1.1.3 retain raw signed curves while1.1.8 weights before both curve/ES. Leading edges follow the original recorded curve");if(bool(options.get("ascending")))policy(object(specification.get("policies")),"source_input_changes",warnings,text(specification.get("id"))+": the original phenotype backend sorts descending and does not apply the constructor ascending flag; no Java reordering is substituted");}
        require(table.rows()==byKey.size(),"Original complete reported sample/term family differs");var seen=new HashSet<Key>();for(int i=0;i<table.rows();i++){var key=new Key(text(table.value(i,"Name")),text(table.value(i,"Term")));var s=byKey.get(key);require(s!=null&&seen.add(key),"Reported term/sample missing, duplicated or invented");same(table.number(i,"ES"),scalar(s.get("es")),0,meter,"Reported ES");if(!method.equals("gsva"))same(table.number(i,"NES"),scalar(s.get("nes")),0,meter,"Reported NES");else require(!table.columns().contains("NES"),"Original GSVA report must not invent a normalized score column");if(permutations>0){same(table.number(i,"NOM p-val"),scalar(s.get("pval")),0,meter,"Reported nominal P");same(table.number(i,"FDR q-val"),scalar(s.get("fdr")),0,meter,"Reported FDR");same(table.number(i,"FWER p-val"),scalar(s.get("fwerp")),0,meter,"Reported FWER");}else require(!table.columns().contains("NOM p-val")&&!table.columns().contains("FDR q-val")&&!table.columns().contains("FWER p-val"),"Non-permutation report exposes original placeholder values as inference");}
        return Map.of("native_walks",walks,"backend_sample_term_states",byKey.size(),"native_null_families",permutations>0?groups.size():0,"gsva_kernel_executed_upstream",method.equals("gsva"));
    }
    private static void leading(Path home,Map<String,Object> summary,String name,List<String> labels,int[] hits,double[] run,Map<String,Object> gmt,Map<String,Object> returned,Meter meter)throws IOException{
        String term=text(summary.get("term"));var results=object(returned.get("_results")!=null?returned.get("_results"):returned.get("results"));Object raw=results.get(term);if(!(raw instanceof Map<?,?> candidate&&candidate.get("lead_genes") instanceof String&&candidate.get("hits") instanceof List<?>)){raw=mapping(results,name);raw=object(raw).get(term);}var result=object(raw);int at=0;boolean positive=scalar(summary.get("es"))>=0;for(int i=1;i<run.length;i++)if(!Double.isNaN(run[at])&&(Double.isNaN(run[i])||(positive?run[i]>run[at]:run[i]<run[at])))at=i;var chosen=new ArrayList<Integer>();for(int hit:hits)if(positive?hit<=at:hit>=at)chosen.add(hit);if(!positive)Collections.reverse(chosen);var genes=new ArrayList<String>();for(int hit:chosen)genes.add(labels.get(hit));require(text(result.get("lead_genes")).equals(String.join(";",genes)),"Original leading-edge gene identity/order changed");String tag=chosen.size()+"/"+list(gmt.get(term)).size();require(text(result.get("tag %")).equals(tag),"Original leading-edge tag fraction changed");double fraction=positive?(at+1.0)/labels.size():(labels.size()-at)/(double)labels.size();String percent=new BigDecimal(fraction*100).setScale(2,RoundingMode.HALF_EVEN).toPlainString()+"%";require(text(result.get("gene %")).equals(percent),"Original gene-fraction annotation changed");
        var matched=new ArrayList<String>();for(int hit:hits)matched.add(strip(labels.get(hit)));require(text(result.get("matched_genes")).equals(String.join(";",matched)),"Original matched-gene annotation changed");var rawHits=list(result.get("hits"));require(rawHits.size()==hits.length,"Original result hit family incomplete");for(int i=0;i<hits.length;i++)require(integer(rawHits.get(i),0,labels.size()-1)==hits[i],"Original result hit order changed");if(result.get("RES") instanceof List<?>){double[] curve=vector(result.get("RES"));require(curve.length==run.length,"Original result running family incomplete");for(int i=0;i<run.length;i++)same(curve[i],run[i],0,meter,"Result running curve");}else{var curve=ScfatesWorkflowData.vector(home,result.get("RES"),10000000);require(curve.size()==run.length,"Original result running family incomplete");for(int i=0;i<run.length;i++)same(curve.number(i),run[i],0,meter,"Result running curve");}meter.identities+=genes.size()+hits.length+3;
    }
    private static Object mapping(Map<String,Object> raw,String key)throws IOException{if("ordered-mapping".equals(raw.get("kind"))){for(Object row:list(raw.get("entries"))){var entry=list(row);Object identity=entry.get(0);if(identity instanceof List<?> tuple&&tuple.size()==1)identity=tuple.get(0);if(key.equals(identity))return entry.get(1);}}else if(raw.containsKey(key))return raw.get(key);throw new IOException("Original sample result mapping missing: "+key);}
    private static String strip(String value){int start=0,end=value.length();while(start<end&&space(value.codePointAt(start)))start+=Character.charCount(value.codePointAt(start));while(end>start&&space(value.codePointBefore(end)))end-=Character.charCount(value.codePointBefore(end));return value.substring(start,end);}
    private static boolean space(int c){return c>=9&&c<=13||c>=28&&c<=32||c==0x85||c==0xa0||c==0x1680||c>=0x2000&&c<=0x200a||c==0x2028||c==0x2029||c==0x202f||c==0x205f||c==0x3000;}
    private static boolean sameData(Object a,Object b,Meter meter)throws IOException{meter.charge(1);if(a instanceof Map<?,?>&&b instanceof Map<?,?>){var x=object(a);var y=object(b);if(!x.keySet().equals(y.keySet()))return false;for(String k:x.keySet())if(!sameData(x.get(k),y.get(k),meter))return false;return true;}if(a instanceof List<?> x&&b instanceof List<?> y){if(x.size()!=y.size())return false;for(int i=0;i<x.size();i++)if(!sameData(x.get(i),y.get(i),meter))return false;return true;}if(a instanceof NextflowParameters.NumberToken||a instanceof Number){try{return Double.doubleToRawLongBits(scalar(a))==Double.doubleToRawLongBits(scalar(b));}catch(IOException bad){return false;}}return java.util.Objects.equals(a,b);}
    private static void scan(Path home,Object raw,GseapyWorkflowRequest.Request request,Meter meter)throws IOException{meter.charge(1);if(raw instanceof Map<?,?>){var m=object(raw);if("binary-numeric-array".equals(m.get("kind"))){var v=ScfatesWorkflowData.vector(home,m,request.maximumMatrixCells());meter.charge(v.size());for(int i=0;i<v.size();i++)if(!(v.value(i) instanceof Boolean)&&!Double.isFinite(v.number(i)))meter.nonfinite++;return;}if("nonfinite-scalar".equals(m.get("kind"))){meter.nonfinite++;return;}for(Object v:m.values())scan(home,v,request,meter);}else if(raw instanceof List<?> values)for(Object v:values)scan(home,v,request,meter);}
    private static void tsv(Path path,CellPhoneDbWorkflowData.Frame frame,long maximum,Meter meter)throws IOException{try(var rows=new CellPhoneDbWorkflowInputs.Rows(path,'\t',maximum)){require(rows.next().equals(frame.columnLabels()),"Complete TSV header changed");for(int i=0;i<frame.rows();i++){var row=rows.next();require(row!=null&&row.size()==frame.columns().size(),"Incomplete original full-precision TSV");for(int j=0;j<row.size();j++){Object expected=frame.value(i,j);String actual=row.get(j);if(expected instanceof Number||expected instanceof NextflowParameters.NumberToken||expected instanceof Map<?,?>){double n=scalar(expected);double parsed=actual.isEmpty()||actual.equalsIgnoreCase("nan")?Double.NaN:actual.equals("inf")?Double.POSITIVE_INFINITY:actual.equals("-inf")?Double.NEGATIVE_INFINITY:Double.parseDouble(actual);same(parsed,n,0,meter,"TSV numeric state");}else require(actual.equals(expected==null?"":text(expected)),"Literal TSV label changed");meter.tsv++;}}require(rows.next()==null,"Extra original TSV rows");}}
    private static List<String> ids(Object raw)throws IOException{Object values=raw;if(raw instanceof Map<?,?> map&&"unordered-set".equals(map.get("kind")))values=map.get("values");var out=new ArrayList<String>();for(Object value:list(values))out.add(value instanceof NextflowParameters.NumberToken n?n.text():value instanceof Number?value.toString():text(value));return out;}
    private static double scalar(Object raw)throws IOException{return ScfatesWorkflowData.scalar(raw);}
    private static double[] vector(Object raw)throws IOException{var values=list(raw);double[] out=new double[values.size()];for(int i=0;i<out.length;i++)out[i]=scalar(values.get(i));return out;}
    private static void same(double actual,double expected,double relative,Meter meter,String where)throws IOException{meter.charge(1);require(Double.isNaN(expected)?Double.isNaN(actual):!Double.isFinite(expected)?actual==expected:relative==0?Double.doubleToRawLongBits(actual)==Double.doubleToRawLongBits(expected):Double.isFinite(actual)&&Math.abs(actual-expected)<=relative*(relative==5e-12?Math.abs(expected):Math.max(1,Math.abs(expected)))+4*Double.MIN_VALUE,"Original source/numeric state differs: "+where);meter.numeric++;}
    private static void policy(Map<String,Object> policies,String name,List<String> warnings,String message)throws IOException{warnings.add(message+". REQUIRED ACTION: read complete source/primitive/report evidence; revise the scientific request on NEW paths or skip dependent inference; never silently repair source states");require(text(policies.get(name)).equals("retain-with-warning"),"Declared "+name+"=fail rejects whole batch: "+message);}
}
